function updateValidation(a,b,c,d){const e='update_validation.php?AutoID='+a+'&Checked='+(b?'1':'0')+'&Testtype='+encodeURIComponent(c)+'&Product='+encodeURIComponent(d);fetch(e).then(a=>a.json()).then(a=>{a.success?console.log('Validation updated successfully'):(console.error('Error:',a.message),alert('Error updating validation: '+a.message))}).catch(a=>{console.error('Fetch error:',a),alert('Error updating validation')})}function updateScenarioValidation(a,b,c,d){const e='update_validation.php?AutoID='+a+'&Checked='+(b?'1':'0')+'&Testtype='+encodeURIComponent(c)+'&Product='+encodeURIComponent(d);fetch(e).then(a=>a.json()).then(a=>{a.success?(console.log('Validation updated successfully'),updateResultDisplay(a,b)):(console.error('Error:',a.message),alert('Error updating validation: '+a.message))}).catch(a=>{console.error('Fetch error:',a),alert('Error updating validation')})}function updateResultDisplay(a,b){const c=document.querySelector('tr[data-autoid="'+a+'"]');if(c){const d=c.querySelector('.result-cell');if(d)if(b)d.innerHTML='<span class="result-badge result-flaky">⚠️ Flaky</span>';else{const e=parseInt(c.getAttribute('data-failed'))||0,f=parseInt(c.getAttribute('data-warning'))||0;e>0?d.innerHTML='<span class="result-badge result-failed">❌ Failed</span>':f>0?d.innerHTML='<span class="result-badge result-flaky">⚠️ Flaky</span>':d.innerHTML='<span class="result-badge result-passed">✅ Passed</span>'}}}function updateScenarioManual(a,b,c,d){const e='update_manual.php?AutoID='+a+'&Manual='+(b?'1':'0')+'&Testtype='+encodeURIComponent(c)+'&Product='+encodeURIComponent(d);fetch(e).then(a=>a.json()).then(a=>{a.success?console.log('Manual flag updated successfully'):(console.error('Error:',a.message),alert('Error updating manual flag: '+a.message))}).catch(a=>{console.error('Fetch error:',a),alert('Error updating manual flag')})}
